"use strict";(self.webpackChunkicecat_connector_doc=self.webpackChunkicecat_connector_doc||[]).push([[386],{795(t,e,o){o.r(e),o.d(e,{comp:()=>d,data:()=>s});var r=o(641);const a={},d=(0,o(262).A)(a,[["render",function(t,e){const o=(0,r.g2)("RouteLink");return(0,r.uX)(),(0,r.CE)("div",null,[e[4]||(e[4]=(0,r.Fv)('<h1 id="bulk-import-csv" tabindex="-1"><a class="header-anchor" href="#bulk-import-csv"><span>Bulk Import (CSV)</span></a></h1><p><strong>Webkul WC Addons → IceCat Connector → Products → Bulk Import</strong> imports (or updates) many catalog products in one run. You upload a CSV, the connector queues every row, and the import happens in the background while a progress dialog keeps count.</p><p><img src="/woocommerce-icecat-connector/images/icecat-connector/bulk-import.webp" alt="The Bulk Import form with a CSV file ready to import"></p><hr><h2 id="the-import-form" tabindex="-1"><a class="header-anchor" href="#the-import-form"><span>The Import Form</span></a></h2><table><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Languages</strong></td><td>The catalog language for every product in this run.</td></tr><tr><td><strong>Upload CSV</strong></td><td>Drag &amp; drop or choose a <code>.csv</code> file (5 MB max). A toast confirms <em>&quot;CSV file selected and ready to import.&quot;</em>; a non-CSV file is rejected with <em>&quot;Invalid file type. Please upload a .csv file.&quot;</em></td></tr><tr><td><strong>Download Method</strong></td><td>Selects which <strong>sample CSV</strong> the two download buttons produce — it does not restrict your file&#39;s format.</td></tr><tr><td><strong>Import With IceCate Category</strong></td><td><em>Yes</em> assigns each product&#39;s own Icecat category; <em>No</em> lets you pick WooCommerce categories for the whole batch.</td></tr><tr><td><strong>Import With WooCommerce Category</strong></td><td>Shown when the previous field is <em>No</em> — one or more store categories for the imported products.</td></tr></tbody></table><h2 id="csv-formats" tabindex="-1"><a class="header-anchor" href="#csv-formats"><span>CSV Formats</span></a></h2><p>Column headers are matched by name (case-insensitive) and may be in any order. Use <strong>Download CSV Sample</strong> / <strong>Download Update CSV Sample</strong> to get a correctly formatted starting file for the selected method.</p><p><strong>Create new products:</strong></p><table><thead><tr><th>Method</th><th>Required headers</th><th>Sample row</th></tr></thead><tbody><tr><td>Icecat ID</td><td><code>icecat_id</code></td><td><code>86199272</code></td></tr><tr><td>GTIN</td><td><code>gstin</code></td><td><code>5900511132816</code></td></tr><tr><td>Product Code &amp; Brand</td><td><code>product_code,brand</code></td><td><code>13281,Trefl</code></td></tr></tbody></table><p><strong>Update existing products</strong> — add a <code>woo_product_id</code> column with the WooCommerce product ID to update instead of create:</p><table><thead><tr><th>Method</th><th>Required headers</th><th>Sample row</th></tr></thead><tbody><tr><td>Icecat ID</td><td><code>icecat_id,woo_product_id</code></td><td><code>116622454,123456</code></td></tr><tr><td>GTIN</td><td><code>gstin,woo_product_id</code></td><td><code>6974260729534,123456</code></td></tr><tr><td>Product Code &amp; Brand</td><td><code>product_code,brand,woo_product_id</code></td><td><code>LUMTB540X1/00,Philips,123456</code></td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">The GTIN header is spelled <code>gstin</code></p><p>The connector (and its sample files) use the header <code>gstin</code> for GTIN columns. A file with a <code>gtin</code> header is rejected as <em>&quot;Invalid CSV format. Please use one of the sample CSV layouts.&quot;</em> — always start from the downloaded sample.</p></div><h2 id="running-the-import" tabindex="-1"><a class="header-anchor" href="#running-the-import"><span>Running the Import</span></a></h2><ol><li>Fill the form, attach the CSV, and click <strong>Import</strong>.</li><li>The rows are queued and a toast confirms <em>&quot;Import started. Products are importing in the background.&quot;</em></li><li>The <strong>Importing Products</strong> dialog opens with a progress bar and running totals.</li></ol><p><img src="/woocommerce-icecat-connector/images/icecat-connector/bulk-import-progress.webp" alt="The Importing Products progress dialog with success and failure counts"></p><ul><li>The dialog polls every few seconds and shows <em>&quot;Processing… Success: X, Failure: Y&quot;</em>, then <em>&quot;Processing completed!&quot;</em></li><li>You can close the dialog and keep working — a <strong>View Progress</strong> button on the form reopens it while the run continues.</li><li>Only one import runs at a time: starting another shows <em>&quot;An import is already in progress. Please wait for it to finish.&quot;</em></li></ul><h2 id="failed-items" tabindex="-1"><a class="header-anchor" href="#failed-items"><span>Failed Items</span></a></h2><p>When a run finishes with failures, the dialog shows <strong>Download Failed Items</strong> — it saves a <code>failed_items.csv</code> containing the rows that could not be imported (unknown IDs, restricted brands, etc.), so you can correct them and re-import just those rows.</p><h2 id="validation-messages" tabindex="-1"><a class="header-anchor" href="#validation-messages"><span>Validation Messages</span></a></h2><table><thead><tr><th>Message</th><th>Meaning</th></tr></thead><tbody><tr><td><em>&quot;Invalid file type. Please upload a .csv file.&quot;</em></td><td>The chosen file isn&#39;t a <code>.csv</code>.</td></tr><tr><td><em>&quot;The CSV file is too large. Please split it into smaller files.&quot;</em></td><td>Over the 5 MB limit.</td></tr><tr><td><em>&quot;Invalid CSV format. Please use one of the sample CSV layouts.&quot;</em></td><td>Headers don&#39;t match any supported layout (check <code>gstin</code>!).</td></tr><tr><td><em>&quot;The CSV file has no rows to import.&quot;</em></td><td>The file only contains the header row.</td></tr></tbody></table><h2 id="related-pages" tabindex="-1"><a class="header-anchor" href="#related-pages"><span>Related Pages</span></a></h2>',22)),(0,r.Lk)("ul",null,[(0,r.Lk)("li",null,[e[1]||(e[1]=(0,r.eW)("Watch imported products arrive: ",-1)),(0,r.bF)(o,{to:"/icecat-connector/manage-products.html"},{default:(0,r.k6)(()=>[...e[0]||(e[0]=[(0,r.eW)("Manage Products",-1)])]),_:1})]),(0,r.Lk)("li",null,[e[3]||(e[3]=(0,r.eW)("Import behavior (status, stock, categories, background processing): ",-1)),(0,r.bF)(o,{to:"/icecat-connector/configuration.html"},{default:(0,r.k6)(()=>[...e[2]||(e[2]=[(0,r.eW)("Configuration",-1)])]),_:1})])])])}]]),s=JSON.parse('{"path":"/icecat-connector/bulk-import.html","title":"Bulk Import (CSV)","lang":"en-US","frontmatter":{"title":"Bulk Import (CSV)","description":"Import or update many Icecat products at once from a CSV of Icecat IDs, GTINs, or product codes — with background processing, live progress, and a failed-items report."},"headers":[{"level":2,"title":"The Import Form","slug":"the-import-form","link":"#the-import-form","children":[]},{"level":2,"title":"CSV Formats","slug":"csv-formats","link":"#csv-formats","children":[]},{"level":2,"title":"Running the Import","slug":"running-the-import","link":"#running-the-import","children":[]},{"level":2,"title":"Failed Items","slug":"failed-items","link":"#failed-items","children":[]},{"level":2,"title":"Validation Messages","slug":"validation-messages","link":"#validation-messages","children":[]},{"level":2,"title":"Related Pages","slug":"related-pages","link":"#related-pages","children":[]}],"git":{},"filePathRelative":"icecat-connector/bulk-import.md"}')}}]);